def find_Product(arr, n):
    if n == 1:
        return arr[0]

    # Initialize result (product) and count variables
    product = 1
    count = 0

    # Traverse through the array
    for i in range(n):
        if arr[i] != 0:
            product *= arr[i]  # Multiply product with non-zero element
            count += 1

    # If there is no non-zero element, return 0
    if count == 0:
        return 0

    # Otherwise, divide product by the number of zero elements
    return product // count

