def pancake_sort(nums):
    def flip(arr, i):
        for j in range(i // 2):
            arr[j], arr[i - j - 1] = arr[i - j - 1], arr[j]

    def max_index(arr, n):
        return max(range(n), key=arr.__getitem__)

    k = len(nums)
    while k > 1:
        # Find the index of the maximum element
        m = max_index(nums[:k])
        if m != k - 1:
            # Flip the array so that the maximum number is at the beginning
            flip(nums, m)
            # Flip the array so that the maximum number is at its correct position
            flip(nums, k - 1)
        k -= 1

